```openscad
// Round-bottom flask support ring on three legs
// Units: mm. Print orientation: legs stand on the bed at z = 0, ring on top.

// ---- Ring ----
ring_od        = 90;   // outer diameter of the ring
ring_id        = 66;   // inner diameter of the ring
ring_thick     = 6;    // ring thickness (Z)
ring_top_z     = 40;   // Z height of the ring's top face

// ---- Legs ----
leg_d          = 8;    // leg diameter
leg_count      = 3;    // number of legs
leg_circle_d   = 78;   // diameter of the circle the leg axes lie on
leg_start_ang  = 0;    // angle of the first leg (deg, 0 = +X axis)
leg_overlap    = 1;    // how far the legs extend into the ring for a solid union

// ---- Misc ----
eps            = 0.5;  // extra length on cutting shapes
$fn            = 128;  // smoothness of curved surfaces

// ---- Derived ----
ring_bottom_z  = ring_top_z - ring_thick;   // Z of the ring's underside

union() {
    // Flat ring (annulus)
    translate([0, 0, ring_bottom_z])
        difference() {
            cylinder(h = ring_thick, d = ring_od);
            translate([0, 0, -eps])
                cylinder(h = ring_thick + 2 * eps, d = ring_id);
        }

    // Three legs running straight down to the bed
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(h = ring_bottom_z + leg_overlap, d = leg_d);
    }
}
```

