```openscad
// Spacer with counterbored socket-head screw hole
// Print orientation: standing on bed, z = 0 to 15, centred on origin

// ---- Dimensions (mm) ----
spacer_d      = 18;    // outer diameter of spacer
spacer_h      = 15;    // total height of spacer
hole_d        = 3.4;   // through-hole diameter (screw clearance)
cbore_d       = 6.5;   // counterbore diameter (socket head)
cbore_depth   = 4;     // counterbore depth from top face (z = 11 to 15)

// ---- Helpers ----
eps           = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // circle resolution

difference() {
    // Main cylinder body
    cylinder(d = spacer_d, h = spacer_h);

    // Through hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = spacer_h + 2 * eps);

    // Counterbore from the top face
    translate([0, 0, spacer_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
```

