```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on the bed (z = 0), rail builds upward (+Z)

// ---------------- Parameters ----------------
plate_len   = 120;  // base plate length along X (mm)
plate_wid   = 40;   // base plate width along Y (mm)
plate_thk   = 6;    // base plate thickness (mm), z = 0..6

rail_w_bot  = 12;   // dovetail width where it meets the plate at z = 6 (mm)
rail_w_top  = 18;   // dovetail width at its top face (mm)
rail_top_z  = 14;   // z height of the rail's top face (mm)
rail_h      = rail_top_z - plate_thk; // dovetail height (mm) = 8

overlap     = 0.01; // small overlap so rail fuses with the plate (mm)

$fn = 64;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X over full length
    // Polygon drawn in (Y, Z); rotate so the extrusion axis becomes +X
    translate([-plate_len/2, 0, 0])
        rotate([90, 0, 90])
            linear_extrude(height = plate_len)
                polygon(points = [
                    [-rail_w_bot/2, plate_thk - overlap],
                    [ rail_w_bot/2, plate_thk - overlap],
                    [ rail_w_top/2, rail_top_z],
                    [-rail_w_top/2, rail_top_z]
                ]);
}
```

