```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on the bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len   = 100;   // base plate length (X)
plate_wid   = 30;    // base plate width (Y)
plate_t     = 6;     // base plate thickness (Z: 0..6)

rail_len    = plate_len; // rail runs full length of plate (X)
rail_bot_w  = 12;    // dovetail width where it meets the plate (z = 6)
rail_top_w  = 16;    // dovetail width at its top face (z = 12)
rail_top_z  = 12;    // top face height of rail

overlap     = 0.5;   // rail sinks this far into plate for a clean union

// ---------------- Derived ----------------
rail_h = rail_top_z - plate_t;   // dovetail height (6 mm)

// ---------------- Modules ----------------
module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);
}

// Trapezoid cross-section drawn in (Y, Z), extruded along X
module dovetail_rail() {
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_bot_w/2, plate_t - overlap], // anchor tab inside plate
                [ rail_bot_w/2, plate_t - overlap],
                [ rail_bot_w/2, plate_t],           // dovetail base (12 wide)
                [ rail_top_w/2, rail_top_z],        // dovetail top (16 wide)
                [-rail_top_w/2, rail_top_z],
                [-rail_bot_w/2, plate_t]
            ]);
}

// ---------------- Assembly ----------------
union() {
    base_plate();
    dovetail_rail();
}
```

