```openscad
// Weighted base for a lab stand rod
// Print orientation: disc flat on bed, boss pointing up (+Z)

// ---------- Dimensions (mm) ----------
disc_d      = 100;   // base disc diameter
disc_h      = 10;    // base disc thickness (z = 0 to 10)
boss_d      = 20;    // boss diameter
boss_top_z  = 30;    // top of boss (boss runs z = 10 to 30)
hole_d      = 8.5;   // rod hole diameter
floor_t     = 2;     // closed floor thickness under the hole (hole bottom at z = 2)
eps         = 0.5;   // overshoot for clean boolean cuts
overlap     = 0.01;  // small overlap so the boss fuses with the disc

$fn = 128;           // resolution for curved surfaces

// ---------- Model ----------
difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);

        // Coaxial boss on top of the disc
        translate([0, 0, disc_h - overlap])
            cylinder(d = boss_d, h = boss_top_z - disc_h + overlap);
    }

    // Rod hole: from above the boss top down to 2 mm above the bed
    translate([0, 0, floor_t])
        cylinder(d = hole_d, h = boss_top_z - floor_t + eps);
}
```

