// Glass stirring rod rest - rectangular block with V-grooves
// Units: mm

// ---------- Block dimensions ----------
block_length = 95;    // X
block_width  = 40;    // Y
block_height = 12;    // Z

// ---------- Groove parameters ----------
groove_count     = 6;    // number of V-grooves
groove_pitch     = 15;   // centre-to-centre spacing along X
groove_top_width = 10;   // width of V at top surface
groove_depth     = 5;    // depth of V (90-degree profile)
overcut          = 1;    // extra cut above top face and past Y faces

// Derived
groove_half_w = groove_top_width / 2;            // 5 mm
ext_half_w    = groove_half_w + overcut * groove_half_w / groove_depth; // keeps 90-degree flank above top
first_x       = -(groove_count - 1) * groove_pitch / 2;

// V-groove cutter, running along Y, apex at depth below top face
module v_groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_width + 2 * overcut, center = true)
            polygon([
                [-ext_half_w, overcut],
                [ ext_half_w, overcut],
                [ 0,         -groove_depth]
            ]);
}

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_length / 2, -block_width / 2, 0])
        cube([block_length, block_width, block_height]);

    // Grooves across the top face
    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, block_height])
            v_groove();
}
