ext_half = half_top + overcut;        // half-width at z = top + overcut (keeps 90 deg V)

// ---------- Groove cutter ----------
module v_groove() {
    // Profile drawn in XZ (2D y -> Z after rotation), extruded along Y
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * overcut, center = true)
            polygon(points = [
                [-ext_half, block_h + overcut],
                [ ext_half, block_h + overcut],
                [ 0,        block_h - groove_depth]
            ]);
}

// ---------- Part ----------
difference() {
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove();
}
