hex_depth    = 4.2;   // hex pocket depth from bottom face (mm)

eps          = 0.5;   // overcut so cutters pass beyond faces (mm)

hole_fn      = 64;    // facets for round hole

// Circumradius of hexagon from across-flats dimension
hex_r = hex_af / (2 * cos(30));

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2*eps, $fn = hole_fn);

    // Hex nut pocket from bottom face.
    // With $fn = 6, vertices sit at 0, 60, 120 deg..., so the edges
    // between 60-120 deg and 240-300 deg are flats parallel to X.
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
