// Split collet - round tube with axial slots from the top
$fn = 96;

// --- Dimensions (mm) ---
od          = 24;    // tube outer diameter
id          = 18;    // tube bore diameter
h           = 30;    // overall height (z = 0 to z = 30)
slot_count  = 3;     // number of axial slots
slot_w      = 1.5;   // slot width
slot_bottom = 20;    // slots run from the top down to this z
eps         = 0.5;   // overlap for clean boolean cuts

// Radial length of the slot cutter: from inside the bore to past the outer wall
slot_r_in   = id / 2 - eps;
slot_r_out  = od / 2 + eps;

difference() {
    // Tube body
    cylinder(d = od, h = h);

    // Bore
    translate([0, 0, -eps])
        cylinder(d = id, h = h + 2 * eps);

    // Axial slots, evenly spaced, first centred on +X
    for (i = [0 : slot_count - 1])
        rotate([0, 0, i * 360 / slot_count])
            translate([slot_r_in, -slot_w / 2, slot_bottom])
                cube([slot_r_out - slot_r_in, slot_w, h - slot_bottom + eps]);
}
