            cube([bar_length, bar_width, plate_thickness]);
        // Bar along Y
        translate([-bar_width/2, -bar_length/2, 0])
            cube([bar_width, bar_length, plate_thickness]);
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_diameter, h = plate_thickness + 2*cut_extra);

    // Arm-end holes
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([hole_offset, 0, -cut_extra])
