// Stepped riser - 3 equal solid steps, climbing in +X
// Print orientation: base on the bed (z = 0), steps build upward (+Z)
// Placement follows the given coordinates: x = 0..45, y = 0..40

// ---------------- Parameters ----------------
num_steps   = 3;    // number of steps
step_length = 15;   // length of each step along X (mm)
step_rise   = 6;    // height added by each step (mm)
depth_y     = 40;   // extrusion depth along Y (mm)

total_length = num_steps * step_length;   // 45 mm overall in X
top_height   = num_steps * step_rise;     // 18 mm top step height

// ---------------- Model ----------------
// Each block i starts at x = i*step_length and runs to the far end (x = 45).
// Its height is (i+1)*step_rise. The blocks overlap, so the union has no
// coplanar internal faces. Every step is solid down to the bed.
union() {
    for (i = [0 : num_steps - 1]) {
        translate([i * step_length, 0, 0])
            cube([total_length - i * step_length, depth_y, (i + 1) * step_rise]);
    }
}
