top_y    = base_y - 2 * chamfer;  // top face width (44 mm)
thin     = 0.01;                  // thickness of the thin slab that defines the top face

// ---------- Model ----------
module display_base() {
    union() {
        // Lower block with sharp bottom edges and vertical sides up to z = side_z
        translate([-base_x / 2, -base_y / 2, 0])
            cube([base_x, base_y, side_z]);

        // Chamfered top section: hull from the full footprint at z = side_z
        // up to the reduced top face at z = base_z
        hull() {
            translate([-base_x / 2, -base_y / 2, side_z - thin])
                cube([base_x, base_y, thin]);
            translate([-top_x / 2, -top_y / 2, base_z - thin])
                cube([top_x, top_y, thin]);
        }
    }
}

display_base();
